@Composable private fun Console(vm:MainViewModel,s:UiState,dark:Boolean,onDark:(Boolean)->Unit){var tab by remember{mutableIntStateOf(0)};var menuExpanded by remember{mutableStateOf(false)};val navItems=listOf(0 to "概览",1 to "卡密",2 to "设备",4 to "预设",9 to "配置");val icons=listOf("⌂","◆","▣","♟","↻","✓","聊","●","↑","⚙");Scaffold(containerColor=Color.Transparent,topBar={TopAppBar(title={Column{Text("喵喵控制中心",fontWeight=FontWeight.Bold);Text("服务运行中",style=MaterialTheme.typography.labelSmall,color=Color(0xFF4ADE80))}},actions={Box{TextButton({menuExpanded=true}){Text("菜单")};DropdownMenu(expanded=menuExpanded,onDismissRequest={menuExpanded=false}){DropdownMenuItem(text={Text("用户 / 账号")},onClick={menuExpanded=false;tab=3});DropdownMenuItem(text={Text("审核员管理")},onClick={menuExpanded=false;tab=5});DropdownMenuItem(text={Text("聊天管理")},onClick={menuExpanded=false;tab=6});DropdownMenuItem(text={Text("头衔申请")},onClick={menuExpanded=false;tab=10});DropdownMenuItem(text={Text("公告管理")},onClick={menuExpanded=false;tab=7});DropdownMenuItem(text={Text("版本管理")},onClick={menuExpanded=false;tab=8});HorizontalDivider();DropdownMenuItem(text={Text("刷新数据")},onClick={menuExpanded=false;vm.refresh()});DropdownMenuItem(text={Text("退出登录")},onClick={menuExpanded=false;vm.logout()})}};TextButton({onDark(!dark)}){Text(if(dark)"浅色" else "深色")}},colors=TopAppBarDefaults.topAppBarColors(containerColor=MaterialTheme.colorScheme.surface))},bottomBar={NavigationBar(containerColor=MaterialTheme.colorScheme.surface){navItems.forEach{(id,n)->NavigationBarItem(tab==id,{tab=id},{Text(icons[id])},label={Text(n)})}}},snackbarHost={SnackbarHost(remember{SnackbarHostState()})}){pad->Box(Modifier.padding(pad).fillMaxSize()){when(tab){0->Dashboard(s);1->Keys(vm,s);2->Devices(vm,s);3->Users(vm,s);4->SharedPresets(vm,s);5->Reviewers(vm,s);6->ChatAdmin(vm,s);10->TitleApplications(vm,s);7->Announcements(vm,s);8->Versions(vm,s);else->RuntimeConfigScreen(vm,s)};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());