@Composable private fun ActivityChart(points:List<ActivityPoint>){Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(16.dp)){Text("24 小时活跃峰值",fontWeight=FontWeight.Bold);Spacer(Modifier.height(12.dp));if(points.isEmpty())Text("正在积累活跃数据（每 5 分钟采样）",color=MaterialTheme.colorScheme.onSurfaceVariant)else Canvas(Modifier.fillMaxWidth().height(150.dp)){val max=(points.maxOfOrNull{it.online}?:1).coerceAtLeast(1);val step=size.width/(points.size-1).coerceAtLeast(1);for(i in 1 until points.size){val a=points[i-1];val b=points[i];drawLine(Color(0xFF3B82F6),Offset((i-1)*step,size.height-a.online.toFloat()/max*size.height),Offset(i*step,size.height-b.online.toFloat()/max*size.height),5f)}}}}}
@Composable private fun MetricCard(n:String,v:Long,d:String){Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(20.dp)){Row(Modifier.padding(20.dp).fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text(n,fontWeight=FontWeight.SemiBold);Text(d,style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Text(v.toString(),style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Black,color=MaterialTheme.colorScheme.primary)}}}

