  item{Header("头衔与身份管理","审核申请，或直接授予管理员、作者和自定义头衔");Button({picking=true;vm.searchUsers("","")},enabled=!s.loading){Text("选择用户授权")}}
  items(s.titleApplications,key={it.id}){a->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("${a.username} · ${a.accountId}",fontWeight=FontWeight.Bold);Text("申请头衔：${a.title}",color=MaterialTheme.colorScheme.primary);Text("申请理由：${a.reason.ifBlank{"未填写"}}");Text("状态：${a.status}",color=MaterialTheme.colorScheme.onSurfaceVariant);if(a.status=="PENDING"){Row{TextButton({vm.reviewTitle(a.id,"APPROVED")}){Text("通过")};TextButton({vm.reviewTitle(a.id,"REJECTED")}){Text("拒绝",color=MaterialTheme.colorScheme.error)}}}}}}
 }
 grant?.let{u->GrantTitleDialog(u,{grant=null}){role,title->vm.grantTitle(u.id,role,title);grant=null}}
}
@Composable private fun GrantTitleDialog(u:UserItem,close:()->Unit,save:(String,String)->Unit){
 var role by remember{mutableStateOf("USER")}
 var title by remember{mutableStateOf("")}
 var confirm by remember{mutableStateOf(false)}
 val valid=title.trim().length<=32 && (role!="USER" || title.trim().isEmpty() || title.trim().length>=2) && !(role=="USER" && title.trim().uppercase() in listOf("作者","管理员","AUTHOR","SYSTEM_ADMIN"))
 if(confirm) AlertDialog(onDismissRequest={confirm=false},title={Text("确认修改身份？")},text={Text("账号：${u.username}\nID：${u.accountId}\n身份：${when(role){"AUTHOR"->"作者";"SYSTEM_ADMIN"->"管理员";else->"普通用户"}}\n头衔：${title.trim().ifBlank{if(role=="USER")"清除自定义头衔" else "使用身份名称"}}\n\n此操作将覆盖该账号的原身份及自定义头衔。")},confirmButton={Button({confirm=false;save(role,title.trim())}){Text("确认提交")}},dismissButton={TextButton({confirm=false}){Text("返回修改")}})
 else AlertDialog(onDismissRequest=close,confirmButton={Button({confirm=true},enabled=valid){Text("下一步")}},dismissButton={TextButton(close){Text("取消")}},title={Text("授权：${u.username}")},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){
 Text("账号 ID：${u.accountId}")
 listOf("USER" to "普通用户", "AUTHOR" to "作者", "SYSTEM_ADMIN" to "管理员").forEach{(r,n)->FilterChip(role==r,{role=r},{Text(n)})}
 Field(title,{title=it},"自定义头衔（最多32字）")
 Text("普通身份留空可清除头衔并撤销作者/管理员身份；系统身份留空使用默认名称。",style=MaterialTheme.typography.bodySmall)
 if(!valid)Text("普通头衔需2–32字，且不能冒用系统身份。",color=MaterialTheme.colorScheme.error)
 }})
}

